  ('d1', 'story', 'What time is it?', 'Ask a stranger for the time, phone in your pocket.', 'Walk up, open your mouth, survive. That''s it.', 1, null, false, 'serious', false, 1, 1, false),
  ('d2', 'story', 'Directions', 'Ask someone the way to a nearby place and listen to the whole answer.', 'Actually listen instead of planning your exit.', 1, null, false, 'serious', false, 2, 1, false),
  ('d3', 'story', 'Their pick', 'Ask a shop assistant or waiter what they would choose, and take it.', null, 1, null, false, 'serious', false, 3, 1, false),
  ('d4', 'story', 'Specific compliment', 'Compliment something precise someone chose (a book, a jacket, a dog), then leave.', 'Specific beats generic: ''great book choice'' beats ''nice''.', 1, null, false, 'serious', false, 4, 1, false),
  ('d5', 'story', 'The discount', 'When paying, ask for a small discount.', 'You''ll probably hear no. That''s the point: smile and pay.', 2, null, false, 'serious', false, 5, 1, false),
  ('d6', 'story', 'Photo, take two', 'Ask a stranger to take your photo, then ask for a second one.', 'Asking again is the real challenge.', 2, null, false, 'serious', false, 6, 1, false),
  ('d7', 'story', 'Three in a row', 'Ask three different strangers a quick question today.', null, 2, null, false, 'serious', false, 7, 1, true),
