  ('d27', 'story', 'Coffee?', 'Ask someone you''ve already talked to out for a coffee.', 'Be specific: "Would you like to grab a coffee this week? Thursday?" A vague "sometime" is easy to dodge.', 5, null, false, 'serious', true, 27, 4, false),
